import { http, HttpResponse } from "msw";
import { cartFromDb, db } from "./data";

const problem = (status: number, title: string, extra: object = {}) =>
  HttpResponse.json({ type: "about:blank", title, status, ...extra }, {
    status,
    headers: { "Content-Type": "application/problem+json" },
  });

export const handlers = [
  http.get("/v1/products", ({ request }) => {
    const url = new URL(request.url);
    const category = url.searchParams.get("category");
    const q = url.searchParams.get("q")?.toLowerCase();
    const items = db.products
      .filter((p) => (!category || p.category === category) && (!q || p.name.toLowerCase().includes(q)))
      .map(({ description, images, stock, specs, updatedAt, ...summary }) => summary);
    return HttpResponse.json({ items, page: 1, pageSize: 20, total: items.length });
  }),

  http.get("/v1/products/:slug", ({ params }) => {
    const product = db.products.find((p) => p.slug === params.slug);
    return product ? HttpResponse.json(product) : problem(404, "Not Found");
  }),

  http.get("/v1/products/:slug/reviews", ({ params }) =>
    HttpResponse.json({ items: db.reviews.filter((r) => r.productSlug === params.slug), nextCursor: null }),
  ),

  // Posting a review as Sam, the user the /v1/me handler says is logged in.
  http.post("/v1/products/:slug/reviews", async ({ params, request }) => {
    const input = (await request.json()) as { rating: number; title: string; body: string };
    const review = {
      id: `r_${db.reviews.length + 1}`,
      productSlug: String(params.slug),
      ...input,
      author: { id: "u_1", name: "Sam" },
      createdAt: "2026-10-01T09:00:00Z",
    };
    db.reviews.unshift(review);
    return HttpResponse.json(review, { status: 201 });
  }),

  http.get("/v1/me", () => HttpResponse.json({ id: "u_1", email: "sam@example.com", name: "Sam" })),

  http.get("/v1/cart", () => HttpResponse.json(cartFromDb())),

  http.put("/v1/cart/items/:slug", async ({ params, request }) => {
    const slug = String(params.slug);
    const product = db.products.find((p) => p.slug === slug);
    if (!product) return problem(404, "Not Found");
    const { quantity } = (await request.json()) as { quantity: number };
    if (quantity > product.stock) {
      return problem(409, "Out of stock", { detail: `Only ${product.stock} left.`, available: product.stock });
    }
    db.cart.set(slug, quantity);
    return HttpResponse.json(cartFromDb());
  }),
];

import { screen } from "@testing-library/react";
import { expect, it } from "vitest";
import { renderWithProviders } from "@/test/render";
import { ProductList } from "./ProductList";

it("loads the products from the API", async () => {
  renderWithProviders(<ProductList />);

  expect(screen.getByRole("status")).toHaveTextContent("Loading products…");

  const list = await screen.findByRole("list", { name: "Products" });
  expect(list.children).toHaveLength(4);
  expect(screen.getByRole("link", { name: "Storm Shell Jacket" })).toBeInTheDocument();
});

it("asks the API for one category", async () => {
  renderWithProviders(<ProductList category="packs" />);

  expect(await screen.findByRole("link", { name: "Trail Pack 45L" })).toBeInTheDocument();
  expect(screen.queryByRole("link", { name: "Storm Shell Jacket" })).not.toBeInTheDocument();
});

import { screen } from "@testing-library/react";
import { delay, http, HttpResponse } from "msw";
import { beforeEach, expect, it } from "vitest";
import { useCartStore } from "@/features/cart/cartStore";
import { db } from "@/mocks/data";
import { server } from "@/mocks/node";
import { renderWithProviders } from "@/test/render";
import { ProductPage } from "./ProductPage";

const renderProduct = (slug: string) =>
  renderWithProviders(<ProductPage />, { path: "/products/:slug", route: `/products/${slug}` });

beforeEach(() => {
  useCartStore.setState({ items: [] });
});

it("adds the product to the cart", async () => {
  const { user } = renderProduct("storm-shell-jacket");

  await user.click(await screen.findByRole("button", { name: "Add Storm Shell Jacket to cart" }));

  expect(await screen.findByText("Added to your cart.")).toBeInTheDocument();
  expect(db.cart.get("storm-shell-jacket")).toBe(1);
});

it("shows how many are left when the API says 409", async () => {
  const { user } = renderProduct("hip-pack-5");

  await user.click(await screen.findByRole("button", { name: /add hip pack 5/i }));

  expect(await screen.findByRole("alert")).toHaveTextContent("Sorry, only 0 left in stock.");
});

it("keeps a guest's item in the browser", async () => {
  server.use(
    http.get("/v1/me", () =>
      HttpResponse.json({ type: "about:blank", title: "Unauthorized", status: 401 }, { status: 401 }),
    ),
  );
  const { user } = renderProduct("storm-shell-jacket");

  await user.click(await screen.findByRole("button", { name: /add storm shell/i }));

  expect(await screen.findByText("Added to your cart.")).toBeInTheDocument();
  expect(useCartStore.getState().items).toEqual([{ slug: "storm-shell-jacket", quantity: 1 }]);
  expect(db.cart.size).toBe(0);
});

it("shows a generic error when the server fails", async () => {
  server.use(http.put("/v1/cart/items/:slug", () => new HttpResponse(null, { status: 500 })));
  const { user } = renderProduct("storm-shell-jacket");

  await user.click(await screen.findByRole("button", { name: /add storm shell/i }));

  expect(await screen.findByRole("alert")).toHaveTextContent("Something went wrong. Try again.");
});

it("shows a generic error when the network is down", async () => {
  server.use(http.put("/v1/cart/items/:slug", () => HttpResponse.error()));
  const { user } = renderProduct("storm-shell-jacket");

  await user.click(await screen.findByRole("button", { name: /add storm shell/i }));

  expect(await screen.findByRole("alert")).toHaveTextContent("Something went wrong. Try again.");
});

it("disables the button while the request is on its way", async () => {
  server.use(http.put("/v1/cart/items/:slug", () => delay("infinite")));
  const { user } = renderProduct("storm-shell-jacket");

  const button = await screen.findByRole("button", { name: /add storm shell/i });
  await user.click(button);

  expect(await screen.findByText("Adding…")).toBeInTheDocument();
  expect(button).toBeDisabled();
});

import { screen } from "@testing-library/react";
import { http, HttpResponse } from "msw";
import { expect, it } from "vitest";
import { db } from "@/mocks/data";
import { server } from "@/mocks/node";
import { renderWithProviders } from "@/test/render";
import { ReviewForm } from "./ReviewForm";

async function fillIn(user: ReturnType<typeof renderWithProviders>["user"]) {
  await user.selectOptions(await screen.findByLabelText("Rating"), "5");
  await user.type(screen.getByLabelText("Title"), "Warm and dry");
  await user.type(screen.getByLabelText("Review"), "Kept the rain out all weekend.");
  await user.click(screen.getByRole("button", { name: "Post review" }));
}

it("posts the review", async () => {
  const { user } = renderWithProviders(<ReviewForm slug="storm-shell-jacket" />);

  await fillIn(user);

  expect(await screen.findByLabelText("Title")).toHaveValue("");
  expect(db.reviews[0]).toMatchObject({ rating: 5, title: "Warm and dry", author: { name: "Sam" } });
});

it("asks a logged-out shopper to log in", async () => {
  server.use(
    http.post("/v1/products/:slug/reviews", () =>
      HttpResponse.json({ type: "about:blank", title: "Unauthorized", status: 401 }, { status: 401 }),
    ),
  );
  const { user } = renderWithProviders(<ReviewForm slug="storm-shell-jacket" />);

  await fillIn(user);

  expect(await screen.findByRole("alert")).toHaveTextContent("Log in to post a review.");
  expect(screen.getByLabelText("Title")).toHaveValue("Warm and dry");
});

