  type: object
  required: [slug, name, priceCents, quantity, lineTotalCents]
  properties:
    slug: { type: string }
    name: { type: string }
    priceCents: { type: integer }
    quantity: { type: integer, minimum: 1, maximum: 10 }
    lineTotalCents: { type: integer }
Cart:
  type: object
  required: [items, subtotalCents, currency]
  properties:
    items:
      type: array
      items: { $ref: '#/components/schemas/CartItem' }
    subtotalCents: { type: integer }
    currency:
      type: string
      const: USD
CartItemInput:
  type: object
  required: [quantity]
  properties:
    quantity: { type: integer, minimum: 1, maximum: 10 }
Problem:
  type: object
  required: [type, title, status]
  properties:
    type: { type: string }
    title: { type: string }
    status: { type: integer }
    detail: { type: string }
    instance: { type: string }
ValidationProblem:
  allOf:
    - $ref: '#/components/schemas/Problem'
    - type: object
      required: [errors]
      properties:
        errors:
          type: object
          additionalProperties: { type: string }
OutOfStockProblem:
  allOf:
    - $ref: '#/components/schemas/Problem'
    - type: object
      required: [available]
      properties:
        available: { type: integer, minimum: 0 }

import { adapterOas } from "@kubb/adapter-oas";
import { pluginClient } from "@kubb/plugin-client";
import { pluginFaker } from "@kubb/plugin-faker";
import { pluginMsw } from "@kubb/plugin-msw";
import { pluginReactQuery } from "@kubb/plugin-react-query";
import { pluginTs } from "@kubb/plugin-ts";
import { pluginZod } from "@kubb/plugin-zod";
import { defineConfig } from "kubb/config";

export default defineConfig({
  input: "./openapi.yaml",
  output: { path: "./src/api/gen", clean: true },
  adapter: adapterOas({ integerType: "number" }),
  plugins: [
    pluginTs(),
    pluginZod(),
    pluginClient({ importPath: "@/lib/kubb-client", validator: "zod" }),
    pluginReactQuery({ hooks: true }),
    pluginFaker({ seed: [42] }),
    pluginMsw({ parser: "faker", handlers: true }),
  ],
});

// The module Kubb's generated functions import. It turns each generated
// call into a call to apiFetch, so every request gets the same base URL,
// credentials, timeout, and ApiError handling as the hand-written ones.
import { z } from "zod";
import { type ApiError, apiFetch } from "./api";

export type RequestConfig = {
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  url: string;
  baseURL?: string;
  path?: object;
  query?: object;
  headers?: object;
  cookies?: object;
  body?: unknown;
  signal?: AbortSignal;
  throwOnError?: boolean;
  contentType?: string | { request?: string; response?: string };
  security?: unknown;
  styles?: object;
  parseAs?: "json" | "text" | "blob" | "arrayBuffer" | "stream";
  validator?: { response?: z.ZodType; error?: unknown };
  client?: typeof client;
};

type DataShape = { body?: unknown; cookies?: unknown; headers?: unknown; path?: unknown; query?: unknown };

export type Options<TData extends DataShape, ThrowOnError extends boolean = true> = Omit<
  RequestConfig,
  keyof DataShape | "url" | "method"
> &
  TData & { throwOnError?: ThrowOnError };

type SuccessOf<TResponses> = TResponses[Extract<keyof TResponses, "200" | "201" | "204">];

// apiFetch throws an ApiError for every error status, so a result always holds data.
export type RequestResult<TResponses, _ThrowOnError extends boolean = true> = { data: SuccessOf<TResponses> };

// What a failed generated hook rejects with.
export type ResponseErrorConfig<_TError = unknown> = ApiError;

export async function client<TResponses, ThrowOnError extends boolean = true>(
  config: RequestConfig,
): Promise<RequestResult<TResponses, ThrowOnError>> {
  const params = (config.path ?? {}) as Record<string, string | number>;
  const path = config.url.replace(/\{(\w+)\}/g, (_, key: string) => encodeURIComponent(String(params[key])));
  const query = new URLSearchParams();
  for (const [key, value] of Object.entries(config.query ?? {})) {
    if (value !== undefined) query.set(key, String(value));
  }

  const data = await apiFetch(query.size ? `${path}?${query}` : path, {
    schema: config.validator?.response ?? z.unknown(),
    method: config.method,
    body: config.body,
    headers: config.headers as Record<string, string> | undefined,
    signal: config.signal,
  });
  return { data: data as SuccessOf<TResponses> };
}

