import { screen } from "@testing-library/react";
import { expect, it } from "vitest";
import { listProductsHandler } from "@/api/gen/handlers";
import { createProductPage, createProductSummary } from "@/api/gen/mocks";
import { server } from "@/mocks/node";
import { renderWithProviders } from "@/test/render";
import { ProductList } from "./ProductList";

it("marks a sold-out product", async () => {
  server.use(
    listProductsHandler(
      createProductPage({ items: [createProductSummary({ name: "Hip Pack 5L", inStock: false })] }),
      { baseURL: "/v1" },
    ),
  );
  renderWithProviders(<ProductList />);

  expect(await screen.findByRole("link", { name: "Hip Pack 5L" })).toBeInTheDocument();
  expect(screen.getByText("Out of stock")).toBeInTheDocument();
});
